tokens:
:root {
  /* ── 바탕 ── */
  --bg: #0B0C0F;                 /* 페이지 바탕. 거의 검은 무채색 */
  --bg-raise: #15171C;           /* 검색창, 읽기 창, 표 머리처럼 한 단 떠 있는 면 */
  --bg-hover: #1C1F25;           /* 목록 행·흐름 날짜 열에 포인터를 올렸을 때 */
  --topbar-bg: rgba(11, 12, 15, 0.88); /* 고정 상단 막대. 뒤 내용을 흐리게 비친다 */

  /* ── 글자 (괄호는 --bg 대비 명암비) ── */
  --text-1: #F2EFEA;             /* 헤드라인, 제목, 본문 (약 17) */
  --text-2: #B9B4AC;             /* 보조 설명, 꼬리표, 증감 (약 9.5) */
  --text-3: #8A867F;             /* 축 눈금, 범례 등 가장 약한 글자 (약 5.4). 글자는 이보다 어둡게 쓰지 않는다 */

  /* ── 선 ── */
  --line-1: #23252B;             /* 구역·행 구분 머리카락선 */
  --line-2: #3A3D45;             /* 입력창·버튼 테두리 */
  --line-grid: #1C1E24;          /* 차트 눈금선 */
  --line-ref: #8A867F;           /* 차트 기준선(+1.0%p, 0) */
  --ref-dash: 4 4;               /* 기준선 점선 간격 (SVG stroke-dasharray) */

  /* ── 강조: 그날 표지의 테두리색. 아래 값은 9/30 표지(복숭아) ── */
  --accent: #F2B39F;
  --accent-text: #F2B39F;        /* 바탕 위 강조 글자. 테두리색이 --bg 대비 4.5 미만인 날은 흰색과 섞어 4.5 이상으로 올린다 */
  --accent-ink: #1B110D;         /* 강조색 면 위 글자 (약 10) */
  --accent-glow: color-mix(in srgb, var(--accent) 18%, transparent); /* 히어로 표지 뒤 번짐, 다음 호 자리의 빛 */
  --accent-soft: color-mix(in srgb, var(--accent) 22%, transparent); /* 검색어 강조 바탕 */

  /* ── 조명 ── */
  --light-beam: rgba(255, 240, 225, 0.075);  /* 히어로 위에서 떨어지는 빛 기둥 */
  --light-shelf: rgba(255, 240, 225, 0.045); /* 선반마다 위에서 비추는 띠 조명 */
  --vignette: rgba(0, 0, 0, 0.55);           /* 히어로 가장자리 어둠 */

  /* ── 선반과 빈 자리 ── */
  --shelf-top: #2C2F36;          /* 선반 윗면 */
  --shelf-face: #16181D;         /* 선반 앞면 */
  --shelf-top-height: 4px;
  --shelf-height: 14px;          /* 윗면을 포함한 전체 두께 */
  --slot-empty-border: 1px dashed #3A3D45;     /* 브리핑 없는 날의 빈 자리·빈 칸 */
  --slot-next-border: 1px dashed var(--accent); /* 다음 호 자리·칸 */

  /* ── 국면 (지금 쓰는 색 그대로). -ink는 그 칸 위 글자색 ── */
  --phase-a: #CB8242;
  --phase-a-ink: #0B0C0F;
  --phase-b: #A96CAF;
  --phase-b-ink: #0B0C0F;
  --phase-c: #056F15;
  --phase-c-ink: #FFFFFF;
  --phase-d: #594D99;
  --phase-d-ink: #FFFFFF;
  --phase-e: #2B97FF;
  --phase-e-ink: #0B0C0F;
  --phase-none: #3A3D45;         /* 국면이 없는 호의 '?' 칸 */
  --phase-none-ink: #F2EFEA;

  /* ── 차트 ── */
  --chart-line: #E6E1D9;         /* 지표 선 */
  --chart-line-width: 1.5px;
  --chart-point: 4px;            /* 날마다 찍는 점 지름 */
  --chart-point-today: 8px;      /* 오늘 점 지름. 색은 --accent */

  /* ── 글꼴 ── */
  --font-sans: "Gothic A1", sans-serif;                 /* 헤드라인, 제목, 본문 */
  --font-display: "Oswald", "Gothic A1", sans-serif;    /* 날짜, 큰 숫자, 국면 글자 */
  --font-mono: "IBM Plex Mono", "Gothic A1", monospace; /* 꼬리표, 축, 표 숫자 */

  /* ── 글자 크기 ── */
  --fs-hero-headline: 48px;
  --fs-metric: 36px;             /* 히어로 지표 값 */
  --fs-hero-date: 32px;
  --fs-section-title: 30px;
  --fs-phase-letter: 30px;       /* 히어로 국면 칸 글자 */
  --fs-phase-name: 22px;         /* 히어로 국면 이름 */
  --fs-lead: 18px;
  --fs-body: 16px;
  --fs-table: 15px;
  --fs-small: 14px;
  --fs-label: 13px;              /* 고정폭 라벨, 선반 꼬리표 */
  --fs-micro: 12px;              /* 차트 눈금, 흐름 칸 아래 날짜, 회차 번호 */

  /* ── 굵기 ── */
  --fw-body: 400;
  --fw-medium: 500;
  --fw-strong: 700;
  --fw-heavy: 800;               /* 헤드라인, 구역 제목 */
  --fw-display: 500;             /* Oswald 숫자 */

  /* ── 줄 높이와 자간 ── */
  --lh-headline: 1.24;
  --lh-title: 1.3;
  --lh-body: 1.6;
  --lh-label: 1.4;
  --lh-numeral: 1;
  --ls-headline: -0.02em;
  --ls-display: 0.01em;
  --ls-mono: 0.02em;

  /* ── 간격 ── */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;
  --space-9: 96px;
  --space-10: 128px;
  --section-gap: 128px;          /* 구역 사이 */
  --section-head-gap: 40px;      /* 구역 머리와 내용 사이 */

  /* ── 둥글기 ── */
  --radius-s: 4px;               /* 국면 칸, 칩 */
  --radius-m: 8px;               /* 버튼, 입력창, 읽기 창 */
  --radius-pill: 999px;          /* 실행 값 알약 */

  /* ── 그림자 (표지에는 아래·뒤로만) ── */
  --shadow-cover-hero: 0 48px 80px -28px rgba(0, 0, 0, 0.9), 0 14px 24px -12px rgba(0, 0, 0, 0.7);
  --shadow-cover: 0 18px 26px -14px rgba(0, 0, 0, 0.85);
  --shadow-cover-hover: 0 28px 36px -16px rgba(0, 0, 0, 0.9);
  --shadow-ledge: 0 12px 20px -8px rgba(0, 0, 0, 0.75);  /* 선반·받침 아래 */
  --shadow-popover: 0 16px 40px rgba(0, 0, 0, 0.6);       /* 읽기 창, 범위 선택 목록 */

  /* ── 레이아웃 ── */
  --page-width: 1440px;
  --content-width: 1280px;
  --gutter: 80px;
  --viewport-check-height: 900px; /* 완료 기준의 '첫 화면' 높이 */
  --topbar-height: 64px;
  --search-width: 360px;         /* 범위 선택 + 입력 */
  --control-height: 40px;        /* 검색창, 작은 버튼 */
  --button-height: 52px;         /* 히어로 버튼 */
  --hero-pad-top: 56px;
  --hero-stage-width: 560px;     /* 빛 기둥 + 표지 */
  --hero-col-gap: 80px;
  --hero-text-width: 640px;
  --phase-cell-hero: 56px;       /* 히어로 국면 칸 한 변 */
  --phase-chip: 28px;            /* 목록 국면 칸 한 변 */

  /* ── 표지 (비율 68:100 고정) ── */
  --cover-aspect: 68 / 100;
  --cover-hero: 440px;
  --cover-shelf: 140px;
  --cover-min: 96px;             /* 이보다 작게 그리지 않는다 */
  --gap-day: 20px;               /* 가판대에서 날과 날 사이 */
  --gap-same-day: 8px;           /* 같은 날 회차 사이 */
  --shelf-row-gap: 56px;         /* 선반과 선반 사이 */
  --tag-gap: 10px;               /* 선반과 꼬리표 사이 */

  /* ── 국면·지표 흐름 ── */
  --flow-label-width: 176px;     /* 줄 이름과 단위 */
  --flow-day-width: 36px;        /* 하루 한 열. 9/2~10/1의 30열 */
  --flow-week-gap: 6px;          /* 월요일 앞에 더하는 간격. 가판대의 주 단위와 리듬을 맞춘다 */
  --flow-cell-gap: 4px;
  --flow-cell-height: 40px;
  --flow-track-height: 112px;    /* 지표 한 줄 높이 */
  --flow-track-gap: 16px;

  /* ── 발행 목록 ── */
  --list-row-height: 60px;
  --col-no: 56px;
  --col-date: 120px;
  --col-phase: 64px;
  --col-num: 104px;              /* 지표 한 열 */
  --col-run: 112px;

  /* ── 움직임 ── */
  --dur-fast: 160ms;
  --dur-base: 280ms;
  --dur-slow: 700ms;             /* 빛 기둥이 켜지는 시간 */
  --ease-out: cubic-bezier(0.2, 0.7, 0.2, 1);
  --lift-hover: 4px;             /* 표지를 올렸을 때 떠오르는 높이 */
  --focus-width: 2px;            /* 초점 테두리. 색은 --accent */
  --focus-offset: 3px;
}
